#!/usr/bin/env python3
"""Collect UCA4 answers from an isolated MySQL Unix socket; no database writes.

Example: python3 generate_uca400.py --mysql /usr/local/mysql/bin/mysql \
  --socket /tmp/task/mysql.sock --output mysql_8_4_11_uca400.json.gz
Answers are never generated by the Go implementation under test.
"""
import argparse
import gzip
import hashlib
import json
import subprocess


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--mysql', required=True)
    p.add_argument('--socket', required=True)
    p.add_argument('--output', required=True)
    args = p.parse_args()

    def query(sql):
        return subprocess.check_output(
            [args.mysql, '--no-defaults', '--protocol=SOCKET', '--socket=' + args.socket,
             '-uroot', '--batch', '--raw', '--skip-column-names'],
            input=sql.encode(), stderr=subprocess.PIPE).decode().splitlines()

    server = query('SELECT VERSION(), @@version_compile_machine;')[0]
    if server != '8.4.11\tarm64':
        raise SystemExit('unexpected oracle build: ' + server)
    values = ['', ' ', '  ', 'a', 'A', 'a ', ' a', 'a  ', 'a b', 'a  b',
              '\0', '\t', '\n', '\r', '\x01', 'a\0', 'a \0', 'a\0 ',
              's', 'ss', 'ß', 'ẞ', 'æ', 'ae', 'œ', 'oe', 'ﬀ', 'ff',
              'é', 'e', 'e\u0301', '\u0301', '\u00ad', 'a\u00ad',
              'a \u00ad', '\u00a0', 'a\u00a0', '\u200b', '\u200d',
              '\u034f', '\ufeff', '中文', '\ufffd', '😀', '😁',
              '\U00010412', '\U00010413', '\ufdfa', '\u04cf', '\u04c0',
              'a' * 128, 'a' * 128 + ' ', 'ß' * 64, 'ss' * 64,
              '\uffff', 'a\uffff', '\uffffa', '\uffff\uffff', ' \uffff ',
              '\uffff\u00ad', '\u00ad\uffff', '\uffff\0', '\0\uffff',
              '\ufffe', '\ufffe\uffff', '\uffff\ufffe']
    # Exhaust a small alphabet around the PAD SPACE boundary, not just words.
    values += [a + b + c for a in ['', ' ', '\t', 'a']
               for b in ['', ' ', '\t', 'a'] for c in ['', ' ', '\t', 'a']]
    values = list(dict.fromkeys(values))

    def expr(s):
        return "CONVERT(X'%s' USING utf8mb4) COLLATE utf8mb4_unicode_ci" % s.encode().hex()

    weights = query('\n'.join('SELECT HEX(WEIGHT_STRING(%s));' % expr(s) for s in values))
    order = []
    for a in values:
        order.extend(int(v) for v in query('\n'.join(
            'SELECT SIGN(STRCMP(%s,%s));' % (expr(a), expr(b)) for b in values)))
    # Independently confirm that MySQL's mb3 collation shares the BMP
    # contract; do not infer this from the Go adapter using a shared backend.
    bmp = [i for i,s in enumerate(values) if all(ord(c) <= 0xffff for c in s)]

    def expr3(s):
        return "CONVERT(X'%s' USING utf8mb3) COLLATE utf8mb3_unicode_ci" % s.encode().hex()

    mb3_weights = query('\n'.join('SELECT HEX(WEIGHT_STRING(%s));' % expr3(values[i]) for i in bmp))
    if mb3_weights != [weights[i] for i in bmp]:
        raise SystemExit('mb3 sample weights differ')
    for i in bmp:
        row = [int(v) for v in query('\n'.join('SELECT SIGN(STRCMP(%s,%s));' %
               (expr3(values[i]), expr3(values[j])) for j in bmp))]
        if row != [order[i * len(values) + j] for j in bmp]:
            raise SystemExit('mb3 sample ordering differs')
    # Scalar weight mapping digest catches table changes beyond sample strings.
    h = hashlib.sha256()
    scalar_weights = []
    scalars = [cp for cp in range(0x10000) if not 0xd800 <= cp <= 0xdfff]
    scalars += [0x10000 + i * 509 for i in range(2048)]
    for start in range(0, len(scalars), 512):
        chunk = scalars[start:start + 512]
        answers = query('\n'.join('SELECT HEX(WEIGHT_STRING(%s));' % expr(chr(cp)) for cp in chunk))
        if len(answers) != len(chunk):
            raise SystemExit('incomplete scalar answers')
        for cp, answer in zip(chunk, answers):
            scalar_weights.append(answer)
            raw = bytes.fromhex(answer)
            h.update(cp.to_bytes(4, 'big') + len(raw).to_bytes(4, 'big') + raw)
    if len(weights) != len(values) or len(order) != len(values) ** 2:
        raise SystemExit('incomplete sample answers')
    data = dict(server=server, collation='utf8mb4_unicode_ci', values=values,
                weights=weights, order=order, scalar_sha256=h.hexdigest(),
                scalar_weights=scalar_weights, mb3_verified_samples=len(bmp))
    with open(args.output, 'wb') as out:
        out.write(gzip.compress((json.dumps(data, ensure_ascii=True, indent=2) + '\n').encode(), mtime=0))


if __name__ == '__main__':
    main()
